import * as React from "react";
import Layout from "../components/layout";
import { useTranslation } from "gatsby-plugin-react-i18next";
import { UserProfile } from "../interfaces";
import data from "../data/data.json";
import { graphql, navigate } from "gatsby";
import images from "../images";
import Modal from "../components/modal";
import ContactForm from "../components/contactForm";
import { SiInstagram } from "react-icons/si";
import { ImFacebook2, ImLinkedin } from "react-icons/im";

interface ServiceCardProps {
  category: string;
  title: string;
  description: string;
  image: string;
}

const ServiceCard: React.FC<ServiceCardProps> = ({
  category,
  title,
  description,
  image,
}) => (
  <article className="bg-primary text-white shadow-2xl max-w-sm w-full cursor-pointer" onClick={() => navigate(`/projects?category=${category}`)}>
    <img
      src={images[image]?.src || ""}
      alt={title}
      className="w-full h-64 object-cover"
    />
    <div className="p-6 text-center">
      <h2 className="text-2xl font-bold mb-2">{title}</h2>
      <p className="text-base">{description}</p>
    </div>
  </article>
);

const WhatWeDo: React.FC = () => {
  const { t } = useTranslation();
  const userData: UserProfile = data;
  const [isModalOpen, setIsModalOpen] = React.useState(false);

  const whatWeDoObj = t("whatWeDo", { returnObjects: true }) as Record<
    string,
    { title: string; description: string; image: string } | string
  >;
  const services = Object.keys(whatWeDoObj).filter(
    (key) => key !== "title" && key !== "intro"
  );

  return (
    <Layout data={userData}>
      <div className="w-full mb-16">
        <article
          className={`${styles.section} w-full flex items-end mt-0 justify-center`}
        >
          <img
            src={images.whatWeDoBanner.src}
            alt={images.whatWeDoBanner.alt}
          />
        </article>

        <article className="ml-0 sm:ml-48 mt-0 sm:-mt-32 p-8 sm:p-0 w-full sm:w-1/2">
          <h1 className="text-3xl sm:text-7xl uppercase">
            {t("whatWeDo.title")}
          </h1>
          <h2 className="text-xl mt-8 w-full ">{t("whatWeDo.intro")}</h2>
        </article>
      </div>

      <div className="w-full px-4 sm:px-12 flex flex-wrap justify-center gap-8 max-w-[1720px] mx-auto mb-16">
        {services.map((key) => {
          const service = whatWeDoObj[key] as {
            category: string;
            title: string;
            description: string;
            image: string;
          };

          return (
            <ServiceCard
              key={key}
              category={service.category || ""}
              title={service.title}
              description={service.description}
              image={service.image}
            />
          );
        })}
      </div>

      <article className="w-full flex justify-center">
        <div className="my-6 mx-auto text-center sm:mx-0 inline-block px-8 sm:px-0">
          <h3 className="text-xl sm:text-3xl text-accent mb-6">
            {t("home.intro_2") || ""}
          </h3>
          <Modal
            isOpen={isModalOpen}
            setIsOpen={setIsModalOpen}
            buttonLabel={t("form.contactUsButton") || ""}
            title={t("form.contactUsButton")}
          >
            <ContactForm />
          </Modal>
          <div className="text-secondary justify-center social">
            <a href={userData.instagram} target="_blank" rel="noreferrer">
              <SiInstagram />
            </a>
            <a href={userData.facebook} target="_blank" rel="noreferrer">
              <ImFacebook2 />
            </a>
            <a href={userData.linkedin} target="_blank" rel="noreferrer">
              <ImLinkedin />
            </a>
          </div>
        </div>
      </article>
    </Layout>
  );
};

export default WhatWeDo;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  container: "flex flex-col justify-center items-center w-full ",
  section: "flex flex-col sm:flex-row gap-6 mb-16 w-full px-4 sm:px-12",
  title: "text-4xl text-accent",
  galleryWrapper: "flex flex-col justify-center items-center w-full",
};
